package com.adent.staff.api;
import com.adent.shared.exception.*; import com.adent.shared.security.CurrentUser; import com.adent.staff.domain.Staff; import com.adent.staff.repository.StaffRepository; import jakarta.validation.Valid; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/staff") @PreAuthorize("hasAnyRole('OWNER','ADMIN')")
public class StaffController { private final CurrentUser current;private final StaffRepository repo;public StaffController(CurrentUser c,StaffRepository r){current=c;repo=r;} @GetMapping public List<Staff> list(){return repo.findByTenantIdOrderByLastNamesAscFirstNamesAsc(current.tenantId());}@GetMapping("/{id}") public Staff get(@PathVariable UUID id){return find(id);}@PostMapping public Staff create(@Valid @RequestBody StaffRequest r){Staff s=new Staff();s.setTenantId(current.tenantId());apply(s,r);return repo.save(s);}@PutMapping("/{id}") public Staff update(@PathVariable UUID id,@Valid @RequestBody StaffRequest r){Staff s=find(id);apply(s,r);return repo.save(s);}@PatchMapping("/{id}/active") public Staff active(@PathVariable UUID id,@RequestParam boolean active){Staff s=find(id);s.setActive(active);return repo.save(s);}@DeleteMapping("/{id}") public void delete(@PathVariable UUID id){Staff s=find(id);try{repo.delete(s);repo.flush();}catch(DataIntegrityViolationException e){throw new BusinessException("No se puede eliminar: el personal tiene registros relacionados. Desactívelo para conservar la trazabilidad.");}} private Staff find(UUID id){return repo.findByIdAndTenantId(id,current.tenantId()).orElseThrow(()->new NotFoundException("Personal no encontrado"));} private void apply(Staff s,StaffRequest r){s.setDocumentType(r.documentType());s.setDocumentNumber(r.documentNumber());s.setFirstNames(r.firstNames());s.setLastNames(r.lastNames());s.setSpecialty(r.specialty());s.setPositionName(r.positionName());s.setPhone(r.phone());s.setEmail(r.email());}}
